    assert_eq!(describe(run("exit 7")), "failed with code 7");
    assert_eq!(describe(run("exit 1")), "failed with code 1");
    assert_eq!(describe(run("kill -9 $$")), "killed by signal 9");
    assert_eq!(describe(run("kill -15 $$")), "killed by signal 15");
