fn run_script(
    script: &str,
    dir: &str,
    vars: &[(&str, &str)],
    input: &str,
) -> io::Result<(String, Option<i32>)> {
    let mut child = Command::new("sh")
        .args(["-c", script])
        .current_dir(dir)
        .envs(vars.iter().copied())
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()?;
